SELECT ROUND(AVG(review_score), 2) AS avg_review_score
FROM fact_orders
WHERE review_score IS NOT NULL;

SELECT ROUND(AVG(delivery_days), 2) AS avg_delivery_days
FROM fact_orders
WHERE delivery_days IS NOT NULL;

SELECT COUNT(DISTINCT order_id) AS delivered_orders_count
FROM fact_orders
WHERE order_status = 'delivered';

SELECT COUNT(DISTINCT order_id) AS canceled_orders_count
FROM fact_orders
WHERE order_status = 'canceled';

SELECT ROUND(MAX(price), 2) AS max_price,
       ROUND(MIN(price), 2) AS min_price
FROM fact_orders;

SELECT COUNT(DISTINCT order_id) AS total_orders
FROM fact_orders
WHERE payment_type = 'credit_card';

SELECT order_id
FROM fact_orders
LIMIT 5;

